import React, { useContext } from "react";
import ProductContext from "./store2/product-context";

import './AddProduct.css';
import CartContext from "../store/cart-context";
const AddProduct = () => {
  const { openProduct, selectedItem } = useContext(ProductContext);
  const { addItems }  =  useContext(CartContext);
  const addToCart = (size) => {
    if (selectedItem) {
      const item = {
        id: selectedItem.id,
        name: selectedItem.name,
        price: selectedItem.price,
        size: size,
        amount: 1, // Set amount to 1
      };
      addItems(item); // Call addItems function from CartContext
    }
  };
  return (
  //   <div>
  //   {openProduct && selectedItem && (
  //     <div className="addProduct">
  //       {selectedItem.map((item) => (
  //         <div key={item.id}>
  //           <h2>{item.name}</h2>
  //           <p>Description: {item.description}</p>
  //           <p>Price: Rs {item.price}</p>
  //           <button onClick={() => addToCart("Large")}>Buy Large {item.large}</button>
  //           <button onClick={() => addToCart("Medium")}>Buy Medium {item.medium}</button>
  //           <button onClick={() => addToCart("Small")}>Buy Small { item.small}</button>
  //         </div>
  //       ))}
  //     </div>
  //   )}
  // </div>
  <div>
  {openProduct && selectedItem && (
    <div className="addProduct">
      <div key={selectedItem.id}>
        <h2>{selectedItem.name}</h2>
        <p>Description: {selectedItem.description}</p>
        <p>Price: Rs {selectedItem.price}</p>
        <button onClick={() => addToCart("Large")}>Buy Large {selectedItem.large}</button>
        <button onClick={() => addToCart("Medium")}>Buy Medium {selectedItem.medium}</button>
        <button onClick={() => addToCart("Small")}>Buy Small {selectedItem.small}</button>
      </div>
    </div>
  )}
</div>
  );
};

export default AddProduct;
